290	    if (changed(periodNumberingFrom) && periodNumberingFromValue !== '' && !isDate(periodNumberingFromValue)) {
291	      this.settingsError.set('Type a period numbering date as yyyy-mm-dd, or leave it blank for sheet-wide numbering.');
292	      return;
293	    }
294	    if (dirty(cap, capFrom) && capValue !== '' && !MONEY.test(capValue)) {
295	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank for no cap.');
296	      return;
297	    }
298	    if (dirty(proofThreshold, proofThresholdFrom) && proofThresholdValue !== '' && !MONEY.test(proofThresholdValue)) {
299	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it blank for none.');
300	      return;
301	    }
302	    this.savingSettings.set(true);
303	    try {
304	      if (dirty(clerkLimit, clerkLimitFrom)) {
305	        const settings = await this.api.setClerkLimit(sheet.id, limit === '' ? null : limit, fromOf(clerkLimitFrom));
306	        settled(clerkLimit);
307	        settled(clerkLimitFrom);
308	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
309	      }
310	      if (dirty(floor, floorFrom)) {
311	        const settings = await this.api.setFloor(sheet.id, floorValue, fromOf(floorFrom));
312	        settled(floor);
313	        settled(floorFrom);
314	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
315	      }
316	      if (dirty(terms, termsFrom)) {
317	        const settings = await this.api.setTerms(sheet.id, Number(termsValue), fromOf(termsFrom));
318	        settled(terms);
319	        settled(termsFrom);
320	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
321	      }
322	      for (const { grade, control, from, value } of gradeTermsValues) {
323	        if (!dirty(control, from)) continue;
324	        const settings = await this.api.setGradeTerms(sheet.id, grade, value === '' ? null : Number(value), fromOf(from));
325	        settled(control);
326	        settled(from);
327	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
328	      }
329	      if (dirty(latePct, latePctFrom)) {
330	        const settings = await this.api.setLatePct(sheet.id, latePctValue, fromOf(latePctFrom));
331	        settled(latePct);
332	        settled(latePctFrom);
333	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
334	      }
335	      if (changed(policyDate)) {
336	        const settings = await this.api.setPolicyDate(sheet.id, policyDateValue === '' ? null : policyDateValue);
337	        settled(policyDate);
338	        if (this.session.sheet()?.id === sheet.id) this.show(settings);
339	      }
